const app = express();
const root = path.dirname(fileURLToPath(import.meta.url));
const asyncRoute = fn => (req,res,next) => Promise.resolve(fn(req,res,next)).catch(next);
const parse = (schema, value) => { const result = schema.safeParse(value); if (!result.success) { const error = new Error(result.error.issues.map(x=>x.message).join('; ')); error.status=400; throw error; } return result.data; };
const emailSchema = z.string().email().max(254).transform(x=>x.toLowerCase());
const passwordSchema = z.string().min(12).max(128).regex(/[A-Z]/,'Inclua uma letra maiúscula').regex(/[a-z]/,'Inclua uma letra minúscula').regex(/\d/,'Inclua um número');
const upload = multer({ storage: multer.memoryStorage(), limits:{ fileSize:config.maxUploadBytes, files:1 }, fileFilter(_req,file,cb){
  const allowed = /\.(pdf|docx|pptx|txt|md|csv|html?|png|jpe?g|webp)$/i.test(file.originalname); cb(allowed ? null : new Error('Formato não permitido.'), allowed);
}});
const profileUpload = multer({ storage:multer.memoryStorage(), limits:{fileSize:2*1024*1024,files:1}, fileFilter(_req,file,cb){
  const allowed=/^image\/(?:png|jpeg|webp)$/.test(file.mimetype); cb(allowed?null:new Error('Use uma imagem PNG, JPEG ou WebP de até 2 MB.'),allowed);
}});

app.set('trust proxy', config.trustProxy);
app.use(helmet({ contentSecurityPolicy:{ directives:{ defaultSrc:["'self'"], scriptSrc:["'self'"], styleSrc:["'self'"], imgSrc:["'self'","data:"], connectSrc:["'self'"], objectSrc:["'none'"], baseUri:["'none'"], frameAncestors:["'none'"] } } }));
app.use(express.json({ limit:'1mb' })); app.use(express.urlencoded({ extended:false, limit:'1mb' })); app.use(cookieParser());
app.use('/api/auth', rateLimit({ windowMs:15*60_000, limit:30, standardHeaders:true, legacyHeaders:false }));

async function audit({teamId,actorId,action,entityType,entityId,data={},ip}) {
  await query('INSERT INTO audit_log(team_id,actor_id,action,entity_type,entity_id,data,ip_hash) VALUES($1,$2,$3,$4,$5,$6,$7)',[teamId||null,actorId||null,action,entityType||null,entityId?String(entityId):null,JSON.stringify(data),ip?sha256(ip):null]);
}
async function issueSession(userId, req, res) {
  const token=randomToken(), csrf=randomToken(24), expires=new Date(Date.now()+config.sessionTtlHours*3600_000);
  await query('INSERT INTO sessions(user_id,token_hash,csrf_token,expires_at,ip_hash,user_agent) VALUES($1,$2,$3,$4,$5,$6)',[userId,sha256(token),csrf,expires,sha256(req.ip||''),String(req.get('user-agent')||'').slice(0,300)]);
  res.cookie(config.cookieName,token,cookieOptions()); return csrf;
}
async function optionalAuth(req,_res,next) {
  try {
    const token=req.cookies[config.cookieName]; if(!token) return next();
    const {rows}=await query(`SELECT s.id session_id,s.csrf_token,u.id user_id,u.email,u.display_name,u.preferred_question_language,m.team_id,r.code role
      FROM sessions s JOIN users u ON u.id=s.user_id JOIN memberships m ON m.user_id=u.id JOIN roles r ON r.id=m.role_id
      WHERE s.token_hash=$1 AND s.expires_at>now() AND u.active ORDER BY m.created_at LIMIT 1`,[sha256(token)]);
    if(rows[0]) req.auth=rows[0]; return next();
  } catch(error){ return next(error); }
}
app.use(optionalAuth);
function requireAuth(req,res,next){ if(!req.auth) return res.status(401).json({error:'Autenticação necessária.'}); next(); }
function requireCsrf(req,res,next){ if(['GET','HEAD','OPTIONS'].includes(req.method)) return next(); if(req.get('x-csrf-token')!==req.auth?.csrf_token) return res.status(403).json({error:'Token CSRF inválido.'}); next(); }
const allow = (...roles)=>(req,res,next)=> roles.includes(req.auth?.role) ? next() : res.status(403).json({error:'Permissão insuficiente.'});
registerLibraryRoutes(app,{requireAuth,requireCsrf,allow});
registerPlatformRoutes(app,{requireAuth,requireCsrf,allow});
registerCertificationRoutes(app,{requireAuth,requireCsrf});

app.get('/api/health', asyncRoute(async(_req,res)=>{ try{await query('SELECT 1');res.json({status:'ok',database:'ok'});}catch{res.status(503).json({status:'degraded',database:'unavailable'});} }));
app.post('/api/auth/register',(_req,res)=>res.status(403).json({error:'Novas contas são criadas somente por gestores ou pelo Revisor Demo.'}));
app.post('/api/auth/login', asyncRoute(async(req,res)=>{
  const body=parse(z.object({email:emailSchema,password:z.string().min(1).max(128)}),req.body); const {rows}=await query('SELECT id,email,display_name,password_hash FROM users WHERE email=$1 AND active',[body.email]);
  if(!rows[0] || !await verifyPassword(body.password,rows[0].password_hash)){ await audit({action:'auth.login_failed',data:{emailHash:sha256(body.email)},ip:req.ip}); return res.status(401).json({error:'E-mail ou senha inválidos.'}); }
  const csrf=await issueSession(rows[0].id,req,res); const membership=(await query('SELECT team_id FROM memberships WHERE user_id=$1 ORDER BY created_at LIMIT 1',[rows[0].id])).rows[0];
  await audit({teamId:membership?.team_id,actorId:rows[0].id,action:'auth.login',entityType:'user',entityId:rows[0].id,ip:req.ip}); res.json({user:{id:rows[0].id,email:rows[0].email,displayName:rows[0].display_name},csrf});
}));
app.post('/api/auth/forgot', asyncRoute(async(req,res)=>{
  const email=parse(z.object({email:emailSchema}),req.body).email; const user=(await query('SELECT id FROM users WHERE email=$1',[email])).rows[0];
  if(user){ const raw=randomToken(); await query("INSERT INTO password_reset_tokens(user_id,token_hash,expires_at) VALUES($1,$2,now()+interval '30 minutes')",[user.id,sha256(raw)]); await audit({actorId:user.id,action:'auth.password_reset_requested',entityType:'user',entityId:user.id,ip:req.ip}); /* Entregue `raw` apenas por um adaptador corporativo server-side; nunca na resposta ou no log. */ }
  res.json({message:'Se a conta existir, as instruções serão enviadas.'});
}));
app.post('/api/auth/reset', asyncRoute(async(req,res)=>{
  const body=parse(z.object({token:z.string().min(20),password:passwordSchema}),req.body); const token=(await query('SELECT * FROM password_reset_tokens WHERE token_hash=$1 AND expires_at>now() AND used_at IS NULL',[sha256(body.token)])).rows[0];
  if(!token)return res.status(400).json({error:'Token inválido ou expirado.'}); await transaction(async c=>{await c.query('UPDATE users SET password_hash=$1,updated_at=now() WHERE id=$2',[await hashPassword(body.password),token.user_id]);await c.query('UPDATE password_reset_tokens SET used_at=now() WHERE id=$1',[token.id]);await c.query('DELETE FROM sessions WHERE user_id=$1',[token.user_id]);}); res.json({message:'Senha atualizada.'});
}));
app.post('/api/auth/logout',requireAuth,requireCsrf,asyncRoute(async(req,res)=>{await query('DELETE FROM sessions WHERE id=$1',[req.auth.session_id]);res.clearCookie(config.cookieName,{path:'/'});await audit({teamId:req.auth.team_id,actorId:req.auth.user_id,action:'auth.logout',ip:req.ip});res.status(204).end();}));
app.post('/api/auth/password',requireAuth,requireCsrf,asyncRoute(async(req,res)=>{const body=parse(z.object({current:z.string(),password:passwordSchema}),req.body);const user=(await query('SELECT password_hash FROM users WHERE id=$1',[req.auth.user_id])).rows[0];if(!await verifyPassword(body.current,user.password_hash))return res.status(400).json({error:'Senha atual incorreta.'});await query('UPDATE users SET password_hash=$1,updated_at=now() WHERE id=$2',[await hashPassword(body.password),req.auth.user_id]);await audit({teamId:req.auth.team_id,actorId:req.auth.user_id,action:'auth.password_changed'});res.json({message:'Senha alterada.'});}));
