app.post('/api/v2/profile/photo',requireAuth,requireCsrf,profileUpload.single('photo'),asyncRoute(async(req,res)=>{if(!req.file)throw Object.assign(new Error('Selecione uma foto.'),{status:400});const key=`${req.auth.team_id}/profiles/${req.auth.user_id}/${crypto.randomUUID()}`;await putPrivate(key,req.file.buffer,req.file.mimetype);await query('UPDATE users SET profile_photo_key=$1,profile_photo_mime=$2,updated_at=now() WHERE id=$3',[key,req.file.mimetype,req.auth.user_id]);await audit({teamId:req.auth.team_id,actorId:req.auth.user_id,action:'profile.photo_updated',entityType:'user',entityId:req.auth.user_id});res.json({hasPhoto:true});}));
