async function performanceFor(teamId,userId,certificationCode){return transaction(async c=>{
  const certification=(await c.query(`SELECT ct.id,ct.code,ct.short_title FROM certification_tracks ct WHERE ct.code=$1`,[certificationCode])).rows[0];
  if(!certification)throw Object.assign(new Error('Certificação não encontrada.'),{status:404});
  const member=(await c.query('SELECT 1 FROM memberships WHERE team_id=$1 AND user_id=$2',[teamId,userId])).rows[0];if(!member)throw Object.assign(new Error('Usuário fora da equipe.'),{status:404});
  const enrollment=await c.query('SELECT COALESCE(percent,0) percent,status FROM certification_enrollments WHERE user_id=$1 AND certification_id=$2',[userId,certification.id]);
  const history=await c.query(`SELECT date_trunc('day',decided_at)::date AS "day",round(avg(score),1) score,count(*)::int attempts FROM simulations WHERE team_id=$1 AND user_id=$2 AND certification_id=$3 AND status='finished' AND approval_status='approved' GROUP BY 1 ORDER BY 1`,[teamId,userId,certification.id]);
  const domains=await c.query(`WITH results AS (SELECT COALESCE(NULLIF(q.official_domain,''),q.category) domain,count(*)::int total,count(*) FILTER(WHERE a.correct)::int correct FROM answers a JOIN simulations s ON s.id=a.simulation_id JOIN questions q ON q.id=a.question_id WHERE s.team_id=$1 AND s.user_id=$2 AND s.certification_id=$3 AND s.status='finished' AND s.approval_status='approved' GROUP BY COALESCE(NULLIF(q.official_domain,''),q.category)) SELECT cd.title domain,COALESCE(sum(r.total),0)::int total,COALESCE(sum(r.correct),0)::int correct,COALESCE(round(100.0*sum(r.correct)/nullif(sum(r.total),0),1),0) accuracy FROM certification_domains cd LEFT JOIN results r ON lower(r.domain)=lower(cd.title) WHERE cd.certification_id=$3 GROUP BY cd.id,cd.title,cd.position ORDER BY cd.position`,[teamId,userId,certification.id]);
  const study=await c.query(`SELECT date_trunc('week',ss.completed_at)::date week,COALESCE(sum(ss.actual_minutes),0)::int minutes FROM study_sessions ss JOIN schedules sc ON sc.id=ss.schedule_id JOIN goals g ON g.id=sc.goal_id WHERE ss.team_id=$1 AND ss.user_id=$2 AND g.certification_id=$3 AND ss.status='completed' GROUP BY 1 ORDER BY 1`,[teamId,userId,certification.id]);
  const coverage=await c.query(`SELECT
    (SELECT count(*)::int FROM document_certifications dc WHERE dc.team_id=$1 AND dc.certification_id=$3) documents,
    (SELECT count(*)::int FROM document_certifications dc JOIN document_reading_progress rp ON rp.document_id=dc.document_id AND rp.user_id=$2 AND rp.percent=100 WHERE dc.team_id=$1 AND dc.certification_id=$3) documents_read,
    (SELECT count(*)::int FROM labs l WHERE l.certification_id=$3) labs,
    (SELECT count(DISTINCT lr.lab_id)::int FROM lab_runs lr JOIN labs l ON l.id=lr.lab_id WHERE lr.team_id=$1 AND lr.user_id=$2 AND l.certification_id=$3 AND lr.status='completed') labs_completed`,[teamId,userId,certification.id]);
  return{certification,progress:enrollment.rows[0]||{percent:0,status:'not_started'},history:history.rows,domains:domains.rows,study:study.rows,coverage:coverage.rows[0]||{documents:0,documents_read:0,labs:0,labs_completed:0}};
},{teamId,userId});}
app.get('/api/v2/analytics/me',requireAuth,asyncRoute(async(req,res)=>{const code=String(req.query.certification||'').toUpperCase()||((await query(`SELECT ct.code FROM certification_enrollments ce JOIN certification_tracks ct ON ct.id=ce.certification_id WHERE ce.user_id=$1 AND ce.is_active LIMIT 1`,[req.auth.user_id])).rows[0]?.code);if(!code)return res.status(409).json({error:'Escolha uma certificação ativa.'});res.json(await performanceFor(req.auth.team_id,req.auth.user_id,code));}));
