app.post('/api/simulations',requireAuth,requireCsrf,asyncRoute(async(req,res)=>{const b=parse(z.object({mode:z.enum(['quick','domain','adaptive','full']).default('quick'),count:z.number().int().min(1).max(60).default(10),durationMinutes:z.number().int().min(5).max(90).default(20),categories:z.array(z.string()).default([]),difficulties:z.array(z.string()).default([])}),req.body);if(b.mode==='full'){b.count=60;b.durationMinutes=90;}const seed=randomToken(12);const candidates=(await transaction(c=>c.query(`SELECT q.id,q.version,q.category,q.difficulty FROM questions q WHERE q.team_id=$1 AND q.status='published' AND ($2::text[]='{}' OR q.category=ANY($2)) AND ($3::text[]='{}' OR q.difficulty=ANY($3)) AND NOT EXISTS(SELECT 1 FROM attempts a WHERE a.user_id=$4 AND a.question_id=q.id AND a.created_at>now()-interval '14 days')`,[req.auth.team_id,b.categories,b.difficulties,req.auth.user_id]),req.auth)).rows;const selected=seededShuffle(candidates,seed).slice(0,b.count);if(selected.length<b.count)return res.status(409).json({error:`Há ${selected.length} questões aprovadas e não recentes; são necessárias ${b.count}.`});const sim=await transaction(async c=>{const s=(await c.query('INSERT INTO simulations(team_id,user_id,mode,seed,question_count,duration_minutes,category_filter,difficulty_filter) VALUES($1,$2,$3,$4,$5,$6,$7,$8) RETURNING *',[req.auth.team_id,req.auth.user_id,b.mode,seed,b.count,b.durationMinutes,JSON.stringify(b.categories),JSON.stringify(b.difficulties)])).rows[0];for(const [i,q] of selected.entries())await c.query('INSERT INTO simulation_questions(simulation_id,question_id,question_version,position) VALUES($1,$2,$3,$4)',[s.id,q.id,q.version,i+1]);return s;},req.auth);res.status(201).json(sim);}));
